// Generated by Gecko from a screen recording. Fails while the bug exists.
import { test, expect } from '@playwright/test'

test('Deleting in Active view removes the correct task', async ({ page }) => {
  await page.goto('/')
  await page.evaluate(() => { localStorage.clear() })
  await page.reload()

  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Call mom")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Pay rent")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Book flights")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("checkbox", { name: "Call mom", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("button", { name: "Active", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("button", { name: "Delete Book flights", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("button", { name: "All", exact: true }).click()
  await page.waitForTimeout(700)
  await page.waitForTimeout(800)

  // Expected behaviour from the bug report
  await expect(page.getByText('Pay rent', { exact: true })).toHaveCount(1);
  await expect(page.getByText('Book flights', { exact: true })).toHaveCount(0);
})
